/**
 * Unit tests for FastDateFormat.applyRules method.
 * Since applyRules is protected, we test it via reflection or by using a subclass/test-spy approach.
 * Because mRules is a protected field initialized during construction, we use reflection to inject mocks.
 */
@RunWith(MockitoJUnitRunner.class)
public class FastDateFormat_applyRules_TriageGen1Test {

    /**
     * Mock interface/class representing the Rule inner class or dependency.
     * Since Rule is a private/protected inner class of FastDateFormat, 
     * we simulate the behavior by mocking the Rule array.
     */
    interface RuleMock {
        void appendTo(StringBuffer buf, Calendar calendar);
    }

    @Test
    public void testApplyRules_Success() throws Exception {
        // Arrange
        String pattern = "yyyy-MM-dd";
        FastDateFormat fdf = FastDateFormat.getInstance(pattern);

        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer("Initial");

        // We need to mock the Rule objects. Since Rule is internal, 
        // we will use reflection to replace the mRules array with mocked Rule objects.
        // Note: In actual Commons Lang, Rule is an internal class. 
        // We must ensure the types match for the reflection to work.

        Rule rule1 = mock(Rule.class);
        Rule rule2 = mock(Rule.class);

        doAnswer(invocation -> {
            StringBuffer b = invocation.getArgument(0);
            b.append("Rule1");
            return null;
        }).when(rule1).appendTo(any(StringBuffer.class), any(Calendar.class));

        doAnswer(invocation -> {
            StringBuffer b = invocation.getArgument(0);
            b.append("Rule2");
            return null;
        }).when(rule2).appendTo(any(StringBuffer.class), any(Calendar.class));

        Rule[] mockRules = new Rule[]{rule1, rule2};

        // Inject mock rules into the instance
        Field rulesField = FastDateFormat.class.getDeclaredField("mRules");
        rulesField.setAccessible(true);
        rulesField.set(fdf, mockRules);

        // Act
        // Using reflection to call the protected method applyRules
        java.lang.reflect.Method applyRulesMethod = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        applyRulesMethod.setAccessible(true);
        StringBuffer result = (StringBuffer) applyRulesMethod.invoke(fdf, calendar, buf);

        // Assert
        assertEquals("InitialRule1Rule2", result.toString());
        assertSame(buf, result);

        verify(rule1, times(1)).appendTo(eq(buf), eq(calendar));
        verify(rule2, times(1)).appendTo(eq(buf), eq(calendar));
    }

    @Test
    public void testApplyRules_EmptyRules() throws Exception {
        // Arrange
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer("Start");

        // Inject empty rules array
        Field rulesField = FastDateFormat.class.getDeclaredField("mRules");
        rulesField.setAccessible(true);
        rulesField.set(fdf, new Rule[0]);

        // Act
        java.lang.reflect.Method applyRulesMethod = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        applyRulesMethod.setAccessible(true);
        StringBuffer result = (StringBuffer) applyRulesMethod.invoke(fdf, calendar, buf);

        // Assert
        assertEquals("Start", result.toString());
        assertSame(buf, result);
    }

    @Test(expected = Exception.class)
    public void testApplyRules_NullRules_ThrowsException() throws Exception {
        // Arrange
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer();

        Field rulesField = FastDateFormat.class.getDeclaredField("mRules");
        rulesField.setAccessible(true);
        rulesField.set(fdf, null);

        // Act
        java.lang.reflect.Method applyRulesMethod = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        applyRulesMethod.setAccessible(true);
        applyRulesMethod.invoke(fdf, calendar, buf);

        // Assert handled by expected exception
    }
}
